import re

TOKEN_SPEC = [
    ("NUMBER", r"\d+(?:\.\d+)?"),
    ("IDENT", r"[A-Za-z_][A-Za-z0-9_]*"),
    ("OP", r"[+\-*/()]"),
    ("SKIP", r"[ \t]+"),
    ("MISMATCH", r"."),
]
MASTER = re.compile("|".join(f"(?P<{n}>{p})" for n, p in TOKEN_SPEC))


def tokenize(text):
    for m in MASTER.finditer(text):
        kind, value = m.lastgroup, m.group()
        if kind == "SKIP":
            continue
        if kind == "MISMATCH":
            raise SyntaxError(f"unexpected {value!r}")
        yield kind, value


class Parser:
    def __init__(self, text, env=None):
        self.tokens = list(tokenize(text))
        self.pos = 0
        self.env = env or {}

    def peek(self):
        return self.tokens[self.pos][1] if self.pos < len(self.tokens) else None

    def take(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expr(self):
        value = self.term()
        while self.peek() in ("+", "-"):
            op = self.take()[1]
            value = value + self.term() if op == "+" else value - self.term()
        return value

    def term(self):
        value = self.factor()
        while self.peek() in ("*", "/"):
            op = self.take()[1]
            value = value * self.factor() if op == "*" else value / self.factor()
        return value

    def factor(self):
        kind, value = self.take()
        if kind == "NUMBER":
            return float(value)
        if kind == "IDENT":
            return float(self.env[value])
        if value == "(":
            inner = self.expr()
            self.take()
            return inner
        if value == "-":
            return -self.factor()
        raise SyntaxError(f"unexpected {value!r}")


def evaluate(text, **env):
    return Parser(text, env).expr()

