import time

MAX_ATTEMPTS = 3
BACKOFF_SECONDS = 0.5


def with_retry(fn, *args, sleep=time.sleep):
    for attempt in range(1, MAX_ATTEMPTS + 1):
        try:
            return fn(*args)
        except ConnectionError:
            if attempt == MAX_ATTEMPTS:
                raise
            sleep(BACKOFF_SECONDS * 2 ** (attempt - 1))


